def groupShiftedStrings(strings):
    def is_shift(s1, s2):
        if len(s1) != len(s2):
            return False
        shift = (ord(s2[0]) - ord(s1[0])) % 26
        return all((ord(s2[i]) - ord(s1[i])) % 26 == shift for i in range(len(s1)))
    groups = []
    for s in sorted(strings):
        placed = False
        for g in groups:
            if is_shift(g[0], s):
                g.append(s)
                placed = True
                break
        if not placed:
            groups.append([s])
    for g in groups: g.sort()
    groups.sort(key=lambda x: x[0])
    return groups

